-- Initial schema for the independent ITSC PostgreSQL application.
-- This migration never accesses the previous MariaDB project.

CREATE TABLE "app_auditoria" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario_id" integer NOT NULL,
  "accion" varchar(60) NOT NULL,
  "entidad" varchar(80) NOT NULL,
  "registro_id" varchar(50),
  "fecha" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "app_auditoria_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "app_auditoria_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "app_auditoria_usuario_id_nonnegative" CHECK ("usuario_id" >= 0)
);

CREATE TABLE "app_intentos" (
  "clave" char(64) NOT NULL,
  "fallos" integer NOT NULL DEFAULT 0,
  "ultimo" timestamp(0) NOT NULL,
  CONSTRAINT "app_intentos_pkey" PRIMARY KEY ("clave")
);

CREATE TABLE "app_usuarios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario" varchar(60) NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "rol" varchar(32) NOT NULL,
  "docente_id" integer,
  "activo" integer NOT NULL DEFAULT 1,
  CONSTRAINT "app_usuarios_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "app_usuarios_usuario_key" UNIQUE ("usuario"),
  CONSTRAINT "app_usuarios_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "app_usuarios_rol_enum" CHECK ("rol" IN ('ADMIN', 'DOCENTE', 'CAJA')),
  CONSTRAINT "app_usuarios_docente_id_nonnegative" CHECK ("docente_id" >= 0),
  CONSTRAINT "app_usuarios_activo_boolean" CHECK ("activo" IN (0,1)),
  CONSTRAINT "app_usuarios_CONSTRAINT_1" CHECK ("rol" <> 'DOCENTE' or "docente_id" is not null)
);

CREATE TABLE "asistencias_demo_historicas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "inscripcion_id" integer NOT NULL,
  "fecha" date NOT NULL,
  "estado" varchar(32) NOT NULL,
  CONSTRAINT "asistencias_demo_historicas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "asistencias_demo_historicas_inscripcion_id_key" UNIQUE ("inscripcion_id", "fecha"),
  CONSTRAINT "asistencias_demo_historicas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "asistencias_demo_historicas_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "asistencias_demo_historicas_estado_enum" CHECK ("estado" IN ('PRESENTE', 'FALTA', 'ATRASO', 'JUSTIFICADA'))
);

CREATE TABLE "asistencias_sesion" (
  "inscripcion_id" integer NOT NULL,
  "sesion_id" integer NOT NULL,
  "oferta_id" integer NOT NULL,
  "minutos_presentes" integer NOT NULL,
  CONSTRAINT "asistencias_sesion_pkey" PRIMARY KEY ("inscripcion_id", "sesion_id"),
  CONSTRAINT "asistencias_sesion_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "asistencias_sesion_sesion_id_nonnegative" CHECK ("sesion_id" >= 0),
  CONSTRAINT "asistencias_sesion_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "asistencias_sesion_minutos_presentes_nonnegative" CHECK ("minutos_presentes" >= 0)
);

CREATE TABLE "aulas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "codigo" varchar(20) NOT NULL,
  "capacidad" integer NOT NULL,
  CONSTRAINT "aulas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "aulas_codigo_key" UNIQUE ("codigo"),
  CONSTRAINT "aulas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "aulas_capacidad_nonnegative" CHECK ("capacidad" >= 0)
);

CREATE TABLE "calificaciones" (
  "inscripcion_id" integer NOT NULL,
  "evaluacion_id" integer NOT NULL,
  "oferta_id" integer NOT NULL,
  "nota" decimal(5,2) NOT NULL,
  CONSTRAINT "calificaciones_pkey" PRIMARY KEY ("inscripcion_id", "evaluacion_id"),
  CONSTRAINT "calificaciones_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "calificaciones_evaluacion_id_nonnegative" CHECK ("evaluacion_id" >= 0),
  CONSTRAINT "calificaciones_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "calificaciones_nota_check" CHECK ("nota" between 1 and 100)
);

CREATE TABLE "cargos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "matricula_id" integer NOT NULL,
  "concepto" varchar(120) NOT NULL,
  "monto" decimal(10,2) NOT NULL,
  "vencimiento" date NOT NULL,
  CONSTRAINT "cargos_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "cargos_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "cargos_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "cargos_CONSTRAINT_1" CHECK ("monto" > 0)
);

CREATE TABLE "carreras" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "codigo" varchar(20) NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "nivel" varchar(50) NOT NULL DEFAULT 'Técnico Superior',
  "duracion_anios" integer NOT NULL DEFAULT 3,
  "regimen" varchar(32) NOT NULL,
  "fuente_url" varchar(500) NOT NULL,
  "activa" integer NOT NULL DEFAULT 1,
  CONSTRAINT "carreras_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "carreras_codigo_key" UNIQUE ("codigo"),
  CONSTRAINT "carreras_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "carreras_duracion_anios_nonnegative" CHECK ("duracion_anios" >= 0),
  CONSTRAINT "carreras_regimen_enum" CHECK ("regimen" IN ('ANUAL', 'SEMESTRAL')),
  CONSTRAINT "carreras_activa_boolean" CHECK ("activa" IN (0,1))
);

CREATE TABLE "cierres_oferta" (
  "oferta_id" integer NOT NULL,
  "minutos_carga" integer NOT NULL,
  "cerrado_por" varchar(120) NOT NULL,
  "fecha" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "cierres_oferta_pkey" PRIMARY KEY ("oferta_id"),
  CONSTRAINT "cierres_oferta_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "cierres_oferta_minutos_carga_check" CHECK ("minutos_carga" > 0),
  CONSTRAINT "cierres_oferta_minutos_carga_nonnegative" CHECK ("minutos_carga" >= 0)
);

CREATE TABLE "defensas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "proyecto_id" integer NOT NULL,
  "fecha" timestamp(0) NOT NULL,
  "aula_id" integer,
  "nota" decimal(5,2),
  "acta" varchar(50),
  CONSTRAINT "defensas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "defensas_acta_key" UNIQUE ("acta"),
  CONSTRAINT "defensas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "defensas_proyecto_id_nonnegative" CHECK ("proyecto_id" >= 0),
  CONSTRAINT "defensas_aula_id_nonnegative" CHECK ("aula_id" >= 0),
  CONSTRAINT "defensas_nota_check" CHECK ("nota" between 0 and 100)
);

CREATE TABLE "docentes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "documento" varchar(25) NOT NULL,
  "nombres" varchar(80) NOT NULL,
  "apellidos" varchar(100) NOT NULL,
  "especialidad" varchar(120) NOT NULL,
  "telefono" varchar(25),
  "correo" varchar(150),
  CONSTRAINT "docentes_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "docentes_documento_key" UNIQUE ("documento"),
  CONSTRAINT "docentes_correo_key" UNIQUE ("correo"),
  CONSTRAINT "docentes_id_nonnegative" CHECK ("id" >= 0)
);

CREATE TABLE "documentos_matricula" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "matricula_id" integer NOT NULL,
  "tipo_documento_id" integer NOT NULL,
  "estado" varchar(32) NOT NULL DEFAULT 'PENDIENTE',
  "fecha_recepcion" date,
  "observacion" varchar(250),
  CONSTRAINT "documentos_matricula_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "documentos_matricula_matricula_id_key" UNIQUE ("matricula_id", "tipo_documento_id"),
  CONSTRAINT "documentos_matricula_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "documentos_matricula_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "documentos_matricula_tipo_documento_id_nonnegative" CHECK ("tipo_documento_id" >= 0),
  CONSTRAINT "documentos_matricula_estado_enum" CHECK ("estado" IN ('PENDIENTE', 'RECIBIDO', 'OBSERVADO'))
);

CREATE TABLE "estudiantes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "registro" varchar(20) NOT NULL,
  "documento" varchar(25) NOT NULL,
  "nombres" varchar(80) NOT NULL,
  "apellidos" varchar(100) NOT NULL,
  "fecha_nacimiento" date NOT NULL,
  "telefono" varchar(25),
  "correo" varchar(150),
  "direccion" varchar(200),
  "fecha_registro" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "estudiantes_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "estudiantes_registro_key" UNIQUE ("registro"),
  CONSTRAINT "estudiantes_documento_key" UNIQUE ("documento"),
  CONSTRAINT "estudiantes_correo_key" UNIQUE ("correo"),
  CONSTRAINT "estudiantes_id_nonnegative" CHECK ("id" >= 0)
);

CREATE TABLE "evaluaciones" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "oferta_id" integer NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "componente" varchar(32) NOT NULL,
  "peso" decimal(6,3) NOT NULL,
  CONSTRAINT "evaluaciones_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "evaluaciones_oferta_id_key" UNIQUE ("oferta_id", "nombre"),
  CONSTRAINT "evaluaciones_id_key" UNIQUE ("id", "oferta_id"),
  CONSTRAINT "evaluaciones_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "evaluaciones_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "evaluaciones_componente_enum" CHECK ("componente" IN ('PRACTICA', 'TEORIA')),
  CONSTRAINT "evaluaciones_peso_check" CHECK ("peso" > 0 and "peso" <= 100)
);

CREATE TABLE "excepciones_asistencia" (
  "inscripcion_id" integer NOT NULL,
  "documento" varchar(250) NOT NULL,
  "resolucion" varchar(100) NOT NULL,
  "aprobada_por" varchar(120) NOT NULL,
  "fecha" date NOT NULL,
  CONSTRAINT "excepciones_asistencia_pkey" PRIMARY KEY ("inscripcion_id"),
  CONSTRAINT "excepciones_asistencia_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "excepciones_asistencia_CONSTRAINT_1" CHECK (octet_length(trim("documento")) > 0 and octet_length(trim("resolucion")) > 0)
);

CREATE TABLE "grupo_integrantes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "grupo_id" integer NOT NULL,
  "matricula_id" integer NOT NULL,
  "fecha" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "grupo_integrantes_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "grupo_integrantes_matricula_id_key" UNIQUE ("matricula_id"),
  CONSTRAINT "grupo_integrantes_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "grupo_integrantes_grupo_id_nonnegative" CHECK ("grupo_id" >= 0),
  CONSTRAINT "grupo_integrantes_matricula_id_nonnegative" CHECK ("matricula_id" >= 0)
);

CREATE TABLE "grupo_materias" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "grupo_id" integer NOT NULL,
  "oferta_id" integer NOT NULL,
  CONSTRAINT "grupo_materias_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "grupo_materias_oferta_id_key" UNIQUE ("oferta_id"),
  CONSTRAINT "grupo_materias_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "grupo_materias_grupo_id_nonnegative" CHECK ("grupo_id" >= 0),
  CONSTRAINT "grupo_materias_oferta_id_nonnegative" CHECK ("oferta_id" >= 0)
);

CREATE TABLE "grupos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "periodo_id" integer NOT NULL,
  "carrera_id" integer NOT NULL,
  "curso" integer NOT NULL,
  "paralelo" varchar(20) NOT NULL,
  "turno" varchar(32) NOT NULL,
  "cupo" integer NOT NULL,
  "tutor_id" integer,
  "estado" varchar(32) NOT NULL DEFAULT 'ACTIVO',
  CONSTRAINT "grupos_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "grupos_uq_grupo_key" UNIQUE ("periodo_id", "carrera_id", "curso", "paralelo", "turno"),
  CONSTRAINT "grupos_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "grupos_periodo_id_nonnegative" CHECK ("periodo_id" >= 0),
  CONSTRAINT "grupos_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "grupos_curso_nonnegative" CHECK ("curso" >= 0),
  CONSTRAINT "grupos_turno_enum" CHECK ("turno" IN ('MAÑANA', 'TARDE', 'NOCHE')),
  CONSTRAINT "grupos_cupo_nonnegative" CHECK ("cupo" >= 0),
  CONSTRAINT "grupos_tutor_id_nonnegative" CHECK ("tutor_id" >= 0),
  CONSTRAINT "grupos_estado_enum" CHECK ("estado" IN ('ACTIVO', 'CERRADO')),
  CONSTRAINT "grupos_CONSTRAINT_1" CHECK ("curso" between 1 and 6),
  CONSTRAINT "grupos_CONSTRAINT_2" CHECK ("cupo" between 1 and 1000)
);

CREATE TABLE "horarios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "oferta_id" integer NOT NULL,
  "aula_id" integer NOT NULL,
  "dia" integer NOT NULL,
  "hora_inicio" time(0) NOT NULL,
  "hora_fin" time(0) NOT NULL,
  CONSTRAINT "horarios_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "horarios_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "horarios_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "horarios_aula_id_nonnegative" CHECK ("aula_id" >= 0),
  CONSTRAINT "horarios_dia_nonnegative" CHECK ("dia" >= 0),
  CONSTRAINT "horarios_CONSTRAINT_1" CHECK ("dia" between 1 and 7),
  CONSTRAINT "horarios_CONSTRAINT_2" CHECK ("hora_fin" > "hora_inicio")
);

CREATE TABLE "inscripciones" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "matricula_id" integer NOT NULL,
  "oferta_id" integer NOT NULL,
  "carrera_id" integer NOT NULL,
  "periodo_id" integer NOT NULL,
  "fecha" date NOT NULL,
  "estado" varchar(32) NOT NULL DEFAULT 'ACTIVA',
  CONSTRAINT "inscripciones_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "inscripciones_matricula_id_key" UNIQUE ("matricula_id", "oferta_id"),
  CONSTRAINT "inscripciones_id_key" UNIQUE ("id", "oferta_id"),
  CONSTRAINT "inscripciones_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "inscripciones_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "inscripciones_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "inscripciones_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "inscripciones_periodo_id_nonnegative" CHECK ("periodo_id" >= 0),
  CONSTRAINT "inscripciones_estado_enum" CHECK ("estado" IN ('ACTIVA', 'RETIRADA', 'CONCLUIDA'))
);

CREATE TABLE "materias" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "carrera_id" integer NOT NULL,
  "codigo" varchar(20) NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "nivel_curso" integer NOT NULL,
  "horas_semanales" integer,
  "fuente_url" varchar(500) NOT NULL,
  CONSTRAINT "materias_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "materias_carrera_id_key" UNIQUE ("carrera_id", "codigo"),
  CONSTRAINT "materias_id_key" UNIQUE ("id", "carrera_id"),
  CONSTRAINT "materias_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "materias_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "materias_nivel_curso_nonnegative" CHECK ("nivel_curso" >= 0),
  CONSTRAINT "materias_horas_semanales_nonnegative" CHECK ("horas_semanales" >= 0)
);

CREATE TABLE "matriculas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "estudiante_id" integer NOT NULL,
  "carrera_id" integer NOT NULL,
  "periodo_id" integer NOT NULL,
  "fecha" date NOT NULL,
  "estado" varchar(32) NOT NULL DEFAULT 'ACTIVA',
  "plan_id" integer NOT NULL,
  CONSTRAINT "matriculas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "matriculas_estudiante_id_key" UNIQUE ("estudiante_id", "carrera_id", "periodo_id"),
  CONSTRAINT "matriculas_id_key" UNIQUE ("id", "carrera_id", "periodo_id"),
  CONSTRAINT "matriculas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "matriculas_estudiante_id_nonnegative" CHECK ("estudiante_id" >= 0),
  CONSTRAINT "matriculas_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "matriculas_periodo_id_nonnegative" CHECK ("periodo_id" >= 0),
  CONSTRAINT "matriculas_estado_enum" CHECK ("estado" IN ('ACTIVA', 'RETIRADA', 'CONCLUIDA')),
  CONSTRAINT "matriculas_plan_id_nonnegative" CHECK ("plan_id" >= 0)
);

CREATE TABLE "modalidades_graduacion" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" varchar(120) NOT NULL,
  CONSTRAINT "modalidades_graduacion_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "modalidades_graduacion_nombre_key" UNIQUE ("nombre"),
  CONSTRAINT "modalidades_graduacion_id_nonnegative" CHECK ("id" >= 0)
);

CREATE TABLE "notas_demo_historicas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "inscripcion_id" integer NOT NULL,
  "evaluacion" varchar(80) NOT NULL,
  "nota" decimal(5,2) NOT NULL,
  "fecha" date NOT NULL,
  CONSTRAINT "notas_demo_historicas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "notas_demo_historicas_inscripcion_id_key" UNIQUE ("inscripcion_id", "evaluacion"),
  CONSTRAINT "notas_demo_historicas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "notas_demo_historicas_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "notas_demo_historicas_CONSTRAINT_1" CHECK ("nota" between 0 and 100)
);

CREATE TABLE "ofertas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "materia_id" integer NOT NULL,
  "carrera_id" integer NOT NULL,
  "periodo_id" integer NOT NULL,
  "docente_id" integer NOT NULL,
  "paralelo" varchar(10) NOT NULL,
  "turno" varchar(32) NOT NULL,
  "cupo" integer NOT NULL,
  CONSTRAINT "ofertas_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ofertas_materia_id_key" UNIQUE ("materia_id", "periodo_id", "paralelo"),
  CONSTRAINT "ofertas_id_key" UNIQUE ("id", "carrera_id", "periodo_id"),
  CONSTRAINT "ofertas_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "ofertas_materia_id_nonnegative" CHECK ("materia_id" >= 0),
  CONSTRAINT "ofertas_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "ofertas_periodo_id_nonnegative" CHECK ("periodo_id" >= 0),
  CONSTRAINT "ofertas_docente_id_nonnegative" CHECK ("docente_id" >= 0),
  CONSTRAINT "ofertas_turno_enum" CHECK ("turno" IN ('MAÑANA', 'TARDE', 'NOCHE')),
  CONSTRAINT "ofertas_cupo_nonnegative" CHECK ("cupo" >= 0)
);

CREATE TABLE "pagos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cargo_id" integer NOT NULL,
  "recibo" varchar(30) NOT NULL,
  "fecha" date NOT NULL,
  "monto" decimal(10,2) NOT NULL,
  "metodo" varchar(32) NOT NULL,
  CONSTRAINT "pagos_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "pagos_recibo_key" UNIQUE ("recibo"),
  CONSTRAINT "pagos_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "pagos_cargo_id_nonnegative" CHECK ("cargo_id" >= 0),
  CONSTRAINT "pagos_metodo_enum" CHECK ("metodo" IN ('EFECTIVO', 'TRANSFERENCIA', 'QR')),
  CONSTRAINT "pagos_CONSTRAINT_1" CHECK ("monto" > 0)
);

CREATE TABLE "pasantias" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "matricula_id" integer NOT NULL,
  "tutor_id" integer,
  "empresa" varchar(150) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_fin" date,
  "horas" integer,
  "estado" varchar(32) NOT NULL,
  CONSTRAINT "pasantias_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "pasantias_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "pasantias_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "pasantias_tutor_id_nonnegative" CHECK ("tutor_id" >= 0),
  CONSTRAINT "pasantias_horas_nonnegative" CHECK ("horas" >= 0),
  CONSTRAINT "pasantias_estado_enum" CHECK ("estado" IN ('SOLICITADA', 'EN_CURSO', 'CONCLUIDA')),
  CONSTRAINT "pasantias_CONSTRAINT_1" CHECK ("fecha_fin" is null or "fecha_fin" >= "fecha_inicio")
);

CREATE TABLE "periodos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" varchar(30) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_fin" date NOT NULL,
  CONSTRAINT "periodos_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "periodos_nombre_key" UNIQUE ("nombre"),
  CONSTRAINT "periodos_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "periodos_CONSTRAINT_1" CHECK ("fecha_fin" >= "fecha_inicio")
);

CREATE TABLE "plan_materias" (
  "plan_id" integer NOT NULL,
  "materia_id" integer NOT NULL,
  "carrera_id" integer NOT NULL,
  CONSTRAINT "plan_materias_pkey" PRIMARY KEY ("plan_id", "materia_id"),
  CONSTRAINT "plan_materias_plan_id_nonnegative" CHECK ("plan_id" >= 0),
  CONSTRAINT "plan_materias_materia_id_nonnegative" CHECK ("materia_id" >= 0),
  CONSTRAINT "plan_materias_carrera_id_nonnegative" CHECK ("carrera_id" >= 0)
);

CREATE TABLE "planes_estudio" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "carrera_id" integer NOT NULL,
  "denominacion" varchar(100) NOT NULL,
  "cohorte" varchar(30) NOT NULL,
  "regla_id" integer NOT NULL,
  CONSTRAINT "planes_estudio_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "planes_estudio_id_key" UNIQUE ("id", "carrera_id"),
  CONSTRAINT "planes_estudio_carrera_id_key" UNIQUE ("carrera_id", "denominacion", "cohorte"),
  CONSTRAINT "planes_estudio_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "planes_estudio_carrera_id_nonnegative" CHECK ("carrera_id" >= 0),
  CONSTRAINT "planes_estudio_regla_id_nonnegative" CHECK ("regla_id" >= 0)
);

CREATE TABLE "prerrequisitos" (
  "plan_id" integer NOT NULL,
  "materia_id" integer NOT NULL,
  "requerida_id" integer NOT NULL,
  CONSTRAINT "prerrequisitos_pkey" PRIMARY KEY ("plan_id", "materia_id", "requerida_id"),
  CONSTRAINT "prerrequisitos_plan_id_nonnegative" CHECK ("plan_id" >= 0),
  CONSTRAINT "prerrequisitos_materia_id_nonnegative" CHECK ("materia_id" >= 0),
  CONSTRAINT "prerrequisitos_requerida_id_nonnegative" CHECK ("requerida_id" >= 0),
  CONSTRAINT "prerrequisitos_CONSTRAINT_1" CHECK ("materia_id" <> "requerida_id")
);

CREATE TABLE "proyectos_graduacion" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "matricula_id" integer NOT NULL,
  "modalidad_id" integer NOT NULL,
  "tutor_id" integer,
  "titulo" varchar(250) NOT NULL,
  "estado" varchar(32) NOT NULL,
  CONSTRAINT "proyectos_graduacion_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "proyectos_graduacion_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "proyectos_graduacion_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "proyectos_graduacion_modalidad_id_nonnegative" CHECK ("modalidad_id" >= 0),
  CONSTRAINT "proyectos_graduacion_tutor_id_nonnegative" CHECK ("tutor_id" >= 0),
  CONSTRAINT "proyectos_graduacion_estado_enum" CHECK ("estado" IN ('PROPUESTO', 'EN_DESARROLLO', 'DEFENDIDO', 'APROBADO'))
);

CREATE TABLE "recuperaciones" (
  "inscripcion_id" integer NOT NULL,
  "matricula_id" integer NOT NULL,
  "nota_prueba" decimal(5,2) NOT NULL,
  "nota_registrada" decimal(5,2) NOT NULL,
  "fecha" date NOT NULL,
  CONSTRAINT "recuperaciones_pkey" PRIMARY KEY ("inscripcion_id"),
  CONSTRAINT "recuperaciones_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "recuperaciones_matricula_id_nonnegative" CHECK ("matricula_id" >= 0),
  CONSTRAINT "recuperaciones_nota_prueba_check" CHECK ("nota_prueba" between 1 and 100)
);

CREATE TABLE "reglas_evaluacion" (
  "id" integer NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "fuente" varchar(500) NOT NULL,
  "minimo" decimal(5,2) NOT NULL DEFAULT 1.00,
  "maximo" decimal(5,2) NOT NULL DEFAULT 100.00,
  "aprobacion" decimal(5,2) NOT NULL DEFAULT 61.00,
  "practica" decimal(4,3) NOT NULL DEFAULT 0.700,
  "teoria" decimal(4,3) NOT NULL DEFAULT 0.300,
  "asistencia" decimal(5,2) NOT NULL DEFAULT 80.00,
  "acceso_recuperacion" decimal(5,2) NOT NULL DEFAULT 40.00,
  "max_rec_anual" integer NOT NULL DEFAULT 3,
  "max_rec_semestral" integer NOT NULL DEFAULT 2,
  CONSTRAINT "reglas_evaluacion_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "reglas_evaluacion_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "reglas_evaluacion_minimo_check" CHECK ("minimo" = 1),
  CONSTRAINT "reglas_evaluacion_maximo_check" CHECK ("maximo" = 100),
  CONSTRAINT "reglas_evaluacion_aprobacion_check" CHECK ("aprobacion" = 61),
  CONSTRAINT "reglas_evaluacion_practica_check" CHECK ("practica" = 0.700),
  CONSTRAINT "reglas_evaluacion_teoria_check" CHECK ("teoria" = 0.300),
  CONSTRAINT "reglas_evaluacion_asistencia_check" CHECK ("asistencia" = 80),
  CONSTRAINT "reglas_evaluacion_acceso_recuperacion_check" CHECK ("acceso_recuperacion" = 40),
  CONSTRAINT "reglas_evaluacion_max_rec_anual_check" CHECK ("max_rec_anual" = 3),
  CONSTRAINT "reglas_evaluacion_max_rec_semestral_check" CHECK ("max_rec_semestral" = 2)
);

CREATE TABLE "resultados_finales" (
  "inscripcion_id" integer NOT NULL,
  "regla_id" integer NOT NULL,
  "promedio" decimal(8,5) NOT NULL,
  "porcentaje_asistencia" decimal(8,5) NOT NULL,
  "excepcion_documentada" integer NOT NULL,
  "estado" varchar(32) NOT NULL,
  "fecha" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "resultados_finales_pkey" PRIMARY KEY ("inscripcion_id"),
  CONSTRAINT "resultados_finales_inscripcion_id_nonnegative" CHECK ("inscripcion_id" >= 0),
  CONSTRAINT "resultados_finales_regla_id_nonnegative" CHECK ("regla_id" >= 0),
  CONSTRAINT "resultados_finales_excepcion_documentada_boolean" CHECK ("excepcion_documentada" IN (0,1)),
  CONSTRAINT "resultados_finales_estado_enum" CHECK ("estado" IN ('APROBADO', 'REPROBADO', 'REPROBADO_ASISTENCIA'))
);

CREATE TABLE "sesiones" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "oferta_id" integer NOT NULL,
  "inicio" timestamp(0) NOT NULL,
  "fin" timestamp(0) NOT NULL,
  "estado" varchar(32) NOT NULL DEFAULT 'PROGRAMADA',
  CONSTRAINT "sesiones_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "sesiones_id_key" UNIQUE ("id", "oferta_id"),
  CONSTRAINT "sesiones_oferta_id_key" UNIQUE ("oferta_id", "inicio"),
  CONSTRAINT "sesiones_id_nonnegative" CHECK ("id" >= 0),
  CONSTRAINT "sesiones_oferta_id_nonnegative" CHECK ("oferta_id" >= 0),
  CONSTRAINT "sesiones_estado_enum" CHECK ("estado" IN ('PROGRAMADA', 'REALIZADA', 'CANCELADA')),
  CONSTRAINT "sesiones_CONSTRAINT_1" CHECK ("fin" > "inicio")
);

CREATE TABLE "tipos_documento" (
